CREATE OR REPLACE FUNCTION public.platform_registration_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e events;BEGIN IF TG_OP='UPDATE' AND NEW.event_id IS DISTINCT FROM OLD.event_id THEN RAISE EXCEPTION 'agreement_event_locked';END IF;IF TG_OP='UPDATE' AND (NEW.status,NEW.checked_in_at) IS NOT DISTINCT FROM(OLD.status,OLD.checked_in_at) THEN RETURN NEW;END IF;IF NEW.status IN('cancelled','declined') THEN RETURN NEW;END IF;SELECT * INTO e FROM events WHERE id=NEW.event_id;IF e.platform_agreement_en IS NULL OR e.platform_agreement_es IS NULL THEN RAISE EXCEPTION 'approved_legal_document_required';END IF;IF coalesce(current_setting('gw.platform_agreement',true),'')<>NEW.event_id::text AND NOT EXISTS(SELECT 1 FROM platform_event_acceptances a WHERE a.rsvp_id=NEW.id AND a.event_id=NEW.event_id AND a.document_id IN(e.platform_agreement_en,e.platform_agreement_es)) THEN RAISE EXCEPTION 'platform_agreement_required';END IF;RETURN NEW;END $$;
CREATE TRIGGER rsvps_platform_agreement BEFORE INSERT OR UPDATE OF status,checked_in_at,event_id ON public.rsvps FOR EACH ROW EXECUTE FUNCTION public.platform_registration_guard();
CREATE OR REPLACE FUNCTION public.registration_agreements_final_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r rsvps;e events;BEGIN SELECT * INTO r FROM rsvps WHERE id=NEW.id;IF NOT FOUND OR r.status IN('cancelled','declined') THEN RETURN NULL;END IF;SELECT * INTO e FROM events WHERE id=r.event_id;IF NOT EXISTS(SELECT 1 FROM platform_event_acceptances a JOIN consent_text_versions c ON c.id=a.document_id AND c.body_sha256=a.content_sha256 WHERE a.rsvp_id=r.id AND a.event_id=e.id AND a.document_id=(CASE WHEN r.language='es' THEN e.platform_agreement_es ELSE e.platform_agreement_en END)) THEN RAISE EXCEPTION 'platform_agreement_required';END IF;IF EXISTS(SELECT 1 FROM event_waivers w WHERE w.event_id=e.id AND w.required AND w.archived_at IS NULL AND NOT EXISTS(SELECT 1 FROM event_waiver_acceptances a WHERE a.rsvp_id=r.id AND a.event_id=e.id AND a.waiver_id=w.id AND a.version=w.version AND a.content_sha256=w.content_sha256)) THEN RAISE EXCEPTION 'waiver_required';END IF;RETURN NULL;END $$;
CREATE CONSTRAINT TRIGGER rsvps_agreements_final AFTER INSERT OR UPDATE OF status,checked_in_at ON public.rsvps DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.registration_agreements_final_guard();
CREATE OR REPLACE FUNCTION public.register_event_agreements(_event_id uuid,_first text,_last text,_phone text,_email text,_language text,_plus_ones integer,_status text,_sms boolean,_mail boolean,_waiver_name text,_answers jsonb,_token text,_terms_ok boolean,_updates_opt_in boolean,_tier_id text,_waivers jsonb,_platform_version uuid) RETURNS TABLE(code text,status text) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e events;v consent_text_versions;rc text;rs text;rid uuid;BEGIN PERFORM unlock_invite(_event_id,_token);IF get_public_event(_event_id) IS NULL THEN RAISE EXCEPTION 'not_open';END IF;SELECT * INTO e FROM events WHERE id=_event_id FOR UPDATE;IF e.platform_agreement_en IS NULL OR e.platform_agreement_es IS NULL THEN RAISE EXCEPTION 'approved_legal_document_required';END IF;IF NOT _terms_ok OR _terms_ok IS NULL THEN RAISE EXCEPTION 'platform_agreement_required';END IF;IF _platform_version IS DISTINCT FROM (CASE WHEN _language='es' THEN e.platform_agreement_es ELSE e.platform_agreement_en END) THEN RAISE EXCEPTION 'agreement_stale';END IF;SELECT * INTO v FROM consent_text_versions WHERE id=_platform_version;IF v.approved_at IS NULL OR v.approval_reference IS NULL OR v.document_url IS NULL THEN RAISE EXCEPTION 'approved_legal_document_required';END IF;PERFORM set_config('gw.platform_agreement',e.id::text,true);SELECT x.code,x.status INTO rc,rs FROM register_attendance_waivers(_event_id,_first,_last,_phone,_email,_language,_plus_ones,_status,_sms,_mail,_waiver_name,_answers,_token,_terms_ok,_updates_opt_in,_tier_id,_waivers) x;SELECT id INTO rid FROM rsvps WHERE checkin_code=rc;INSERT INTO platform_event_acceptances(event_id,rsvp_id,document_id,content_sha256,user_id) SELECT e.id,rid,v.id,v.body_sha256,r.user_id FROM rsvps r WHERE r.id=rid ON CONFLICT DO NOTHING;PERFORM set_config('gw.platform_agreement','',true);RETURN QUERY SELECT rc,rs;END $$;
REVOKE ALL ON FUNCTION public.register_event_agreements(uuid,text,text,text,text,text,integer,text,boolean,boolean,text,jsonb,text,boolean,boolean,text,jsonb,uuid) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.register_event_agreements(uuid,text,text,text,text,text,integer,text,boolean,boolean,text,jsonb,text,boolean,boolean,text,jsonb,uuid) TO anon,authenticated;
DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef('public.checkin_blocker(uuid)'::regprocedure) INTO d;d:=replace(d,'WHEN(e.requires_waiver','WHEN e.platform_agreement_en IS NULL OR e.platform_agreement_es IS NULL THEN ''approved_legal_document_required'' WHEN NOT EXISTS(SELECT 1 FROM platform_event_acceptances a JOIN consent_text_versions c ON c.id=a.document_id AND c.body_sha256=a.content_sha256 WHERE a.rsvp_id=r.id AND a.event_id=e.id AND a.document_id=(CASE WHEN r.language=''es'' THEN e.platform_agreement_es ELSE e.platform_agreement_en END)) THEN ''platform_agreement_required'' WHEN(e.requires_waiver');EXECUTE d;END $$;
CREATE OR REPLACE FUNCTION public.my_platform_event_acceptance(_code text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_agg(jsonb_build_object('document_id',c.id,'version',c.version,'locale',c.locale,'url',c.document_url,'accepted_at',a.accepted_at)) FROM rsvps r JOIN platform_event_acceptances a ON a.rsvp_id=r.id AND a.event_id=r.event_id JOIN consent_text_versions c ON c.id=a.document_id WHERE length(_code)>=6 AND r.checkin_code=_code $$;
REVOKE ALL ON FUNCTION public.my_platform_event_acceptance(text) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.my_platform_event_acceptance(text) TO anon,authenticated;
REVOKE ALL ON FUNCTION public.platform_registration_guard(),public.registration_agreements_final_guard(),public.pin_platform_event_agreement(),public.host_waiver_event_guard(),public.legacy_waiver_host_guard(),public.legacy_waiver_selection_guard() FROM PUBLIC,anon,authenticated;